from collections import deque
from time import monotonic

class DynamicBatcher:
    def __init__(self, max_batch_size=8, max_wait_seconds=0.01):
        self.queue = deque()
        self.max_batch_size = max_batch_size
        self.max_wait_seconds = max_wait_seconds

    def submit(self, request):
        self.queue.append((monotonic(), request))

    def get_batch(self):
        if not self.queue:
            return []
        oldest_time = self.queue[0][0]
        if len(self.queue) < self.max_batch_size and monotonic() - oldest_time < self.max_wait_seconds:
            return []
        return [self.queue.popleft()[1] for _ in range(min(len(self.queue), self.max_batch_size))]

batcher = DynamicBatcher(max_batch_size=4, max_wait_seconds=0.01)
batcher.submit({"id": "request-1", "prompt": "Explain attention"})
